"""Offline export of a saved split plan into a classification data package.

The produced ZIP contains three set directories (``train``, ``validation``,
``test``), each laid out as an ImageFolder tree of category directories,
plus a UTF-8 JSON manifest describing the plan and every packaged sample.

Everything in the archive is derived solely from the saved plan: later
imports, batch label updates and undos never affect an export of an older
plan, and an export never writes back into the workspace.

The archive bytes are deterministic for the same plan, options and source
file contents.  In particular they do not depend on workspace location,
target path, file modification times or the export time.  Source media is
streamed one sample at a time, so memory use does not grow with the total
number of media bytes.
"""

from __future__ import annotations

import hashlib
import io
import json
import os
import posixpath
import shutil
import unicodedata
import zipfile
from dataclasses import dataclass
from pathlib import Path
from typing import Any, BinaryIO

from .splits import SET_NAMES, SplitError

MANIFEST_ENTRY = "manifest.json"
PACKAGE_SCHEMA_VERSION = 1
_CHUNK_SIZE = 1024 * 1024


class ExportError(ValueError):
    """An export request failed (bad plan, unreadable source, bad target)."""


@dataclass(frozen=True)
class PlannedSample:
    digest: str
    label: str  # "" means unlabeled
    source: str


@dataclass(frozen=True)
class ExportPlan:
    name: str
    seed: int
    ratios: dict[str, str]
    members: dict[str, list[PlannedSample]]


def parse_saved_plan(data: Any) -> ExportPlan:
    """Validate and normalize a loaded split-plan JSON payload for export.

    Only the fields export depends on are examined; damaged or inconsistent
    plans raise :class:`ExportError` rather than producing a partial
    package.
    """
    if not isinstance(data, dict):
        raise ExportError("Split plan record is malformed")
    if data.get("schema_version") != 1:
        raise ExportError("Unsupported split plan schema version")
    name = data.get("name")
    if not isinstance(name, str):
        raise ExportError("Split plan record is missing its name")
    seed = data.get("seed")
    if not isinstance(seed, int) or isinstance(seed, bool):
        raise ExportError("Split plan record is missing its seed")
    ratios = data.get("ratios")
    if not isinstance(ratios, dict):
        raise ExportError("Split plan record is missing its ratios")
    ratio_map: dict[str, str] = {}
    for set_name in SET_NAMES:
        value = ratios.get(set_name)
        if not isinstance(value, str):
            raise ExportError(f"Split plan record is missing ratio for {set_name}")
        ratio_map[set_name] = value

    sets = data.get("sets")
    if not isinstance(sets, dict):
        raise ExportError("Split plan record is missing its set assignments")

    members: dict[str, list[PlannedSample]] = {}
    seen: set[str] = set()
    for set_name in SET_NAMES:
        set_payload = sets.get(set_name)
        if not isinstance(set_payload, dict):
            raise ExportError(f"Split plan record is missing set {set_name}")
        raw_members = set_payload.get("members")
        if not isinstance(raw_members, list):
            raise ExportError(f"Split plan record is missing members for {set_name}")
        planned: list[PlannedSample] = []
        for member in raw_members:
            if not isinstance(member, dict):
                raise ExportError(f"Split plan record has a bad member in {set_name}")
            digest = member.get("sha256")
            label = member.get("label")
            source = member.get("source")
            if (
                not isinstance(digest, str)
                or not digest
                or not isinstance(label, str)
                or not isinstance(source, str)
            ):
                raise ExportError(f"Split plan record has a bad member in {set_name}")
            if digest in seen:
                raise ExportError(
                    f"Split plan record lists {digest} in more than one set"
                )
            seen.add(digest)
            planned.append(PlannedSample(digest=digest, label=label, source=source))
        members[set_name] = planned
    return ExportPlan(name=name, seed=seed, ratios=ratio_map, members=members)


def build_category_map(labels: list[str]) -> dict[str, str]:
    """Assign each distinct label a unique, safe category directory name.

    Labels are arbitrary user strings (Chinese, separators, dots, trailing
    spaces).  Directories must stay distinct even on case-insensitive
    filesystems and must never be ``.``/``..`` or contain a path
    separator, so unrepresentable or colliding labels get a short
    content-derived suffix.  The mapping is a pure function of the sorted
    label set, hence stable across workspaces and runs.
    """
    result: dict[str, str] = {}
    used: set[str] = set()
    for label in sorted(set(labels)):
        candidate = _safe_dir_name(label)
        if candidate in used:
            digest = hashlib.sha256(
                b"vision-workbench-category\x00" + label.encode("utf-8")
            ).hexdigest()[:10]
            stem = candidate if candidate != "_" else ""
            candidate = f"{stem}-{digest}" if stem else f"cat-{digest}"
        used.add(candidate)
        result[label] = candidate
    return result


def _safe_dir_name(label: str) -> str:
    """Best-effort readable directory name for one label.

    Returned names contain no path separators or control characters, are
    not ``.``/``..``, and have their trailing dots/spaces trimmed (Windows
    would do that anyway).  A label with nothing representable left maps to
    the reserved placeholder ``_`` (and gets a disambiguating suffix from
    the caller if needed).
    """
    chars: list[str] = []
    for char in label:
        category = unicodedata.category(char)
        if (
            char in '/\\:*?"<>|'
            or category.startswith("C")  # control/format surrogates
            or char == "\u007f"
        ):
            chars.append("_")
        else:
            chars.append(char)
    name = "".join(chars).strip().rstrip(".").strip()
    if not name:
        return "_"
    return name


def export_package(
    plan: ExportPlan,
    target: Path | str,
    *,
    skip_unlabeled: bool = False,
) -> dict[str, Any]:
    """Export ``plan`` to a ZIP file at ``target``.

    Returns a JSON-serializable summary naming the plan, the total number
    of samples actually written, the per-set category distribution and the
    number of skipped unlabeled samples.

    Raises :class:`ExportError` when the target already exists, any sample
    is unlabeled without ``skip_unlabeled``, a source file is missing or
    unreadable, or its bytes do not hash to the planned digest.  Nothing
    is written to the target in any of those cases.
    """
    target = Path(target)

    all_samples = [
        sample
        for set_name in SET_NAMES
        for sample in plan.members[set_name]
    ]

    unlabeled = {sample.digest for sample in all_samples if sample.label == ""}
    if unlabeled and not skip_unlabeled:
        raise ExportError(
            "plan contains unlabeled samples; refusing to export "
            f"(first: {sorted(unlabeled)[0]}); use --skip-unlabeled to skip them"
        )

    included: dict[str, list[PlannedSample]] = {}
    skipped_counts: dict[str, int] = {}
    for set_name in SET_NAMES:
        members = plan.members[set_name]
        included[set_name] = [
            sample for sample in members if sample.label != ""
        ]
        skipped_counts[set_name] = len(members) - len(included[set_name])

    labels = sorted({sample.label for samples in included.values() for sample in samples})
    category_by_label = build_category_map(labels)

    # Validate every source and hash its bytes before opening the target,
    # so a missing or mismatched file never creates or alters the ZIP.
    # Digests are re-verified during streaming as well, so a file changing
    # between this pass and the write cannot pass off altered content.
    verified: dict[str, tuple[str, int]] = {}
    for sample in all_samples:
        if sample.label == "":
            continue
        size = _verify_source(sample, source_path(sample))
        verified[sample.digest] = (source_path(sample), size)

    manifest_payload = _build_manifest(
        plan, included, category_by_label, skipped_counts
    )
    manifest_bytes = (
        json.dumps(manifest_payload, ensure_ascii=False, sort_keys=True, indent=2)
        + "\n"
    ).encode("utf-8")

    # Sorted archive entries and fixed metadata make the output byte-stable.
    infos: list[zipfile.ZipInfo] = []
    for set_name in SET_NAMES:
        infos.append(_directory_info(""))  # placeholder removed below
    infos = []
    top_dirs = sorted(set(SET_NAMES) | {posixpath.split(entry)[0] for entry in []})

    entries: list[tuple[str, Any]] = []  # (arcname, kind, payload)
    entries.append((MANIFEST_ENTRY, "file", ("manifest", manifest_bytes)))
    for set_name in SET_NAMES:
        entries.append((f"{set_name}/", "dir", None))
    for label in labels:
        category = category_by_label[label]
        for set_name in SET_NAMES:
            entries.append((f"{set_name}/{category}/", "dir", None))
    for set_name in SET_NAMES:
        for sample in included[set_name]:
            category = category_by_label[sample.label]
            _, extension = os.path.splitext(source_path(sample))
            arcname = f"{set_name}/{category}/{sample.digest}{extension}"
            entries.append((arcname, "sample", sample))
    # Deterministic order: manifest, directories (and files) by name.
    manifest_entry = entries[0]
    rest = sorted(entries[1:], key=lambda entry: entry[0])
    ordered = [manifest_entry, *rest]

    temporary = target.with_name(f".{target.name}.tmp") if target.parent != Path("") else Path(f".{target.name}.tmp")

    def write_archive(stream: BinaryIO) -> None:
        with zipfile.ZipFile(stream, "w", compression=zipfile.ZIP_DEFLATED) as archive:
            for arcname, kind, payload in ordered:
                info = zipfile.ZipInfo(arcname, date_time=(1980, 1, 1, 0, 0, 0))
                info.external_attr = (
                    (0o755 << 16) if kind == "dir" else (0o644 << 16)
                )
                info.create_system = 3
                info.compress_type = zipfile.ZIP_DEFLATED
                if kind == "dir":
                    archive.writestr(info, b"")
                elif kind == "manifest":
                    archive.writestr(info, payload)
                else:
                    # Stream the media file through the archiver in chunks
                    # while re-hashing: content is never fully buffered.
                    size, digest = _stream_member(archive, info, payload)
                    expected_path, expected_size = verified[payload.digest]
                    if size != expected_size or digest != payload.digest:
                        raise ExportError(
                            f"source for {payload.digest} changed while "
                            "reading; export aborted"
                        )

    try:
        _write_target(target, temporary, write_archive)
    except ExportError:
        temporary.unlink(missing_ok=True)
        raise
    except OSError as error:
        temporary.unlink(missing_ok=True)
        raise ExportError(f"cannot write export archive: {error}") from error

    distributions: dict[str, dict[str, int]] = {}
    for set_name in SET_NAMES:
        counts: dict[str, int] = {}
        for sample in included[set_name]:
            counts[sample.label] = counts.get(sample.label, 0) + 1
        distributions[set_name] = dict(sorted(counts.items()))

    total = sum(len(samples) for samples in included.values())
    return {
        "plan": plan.name,
        "target": os.fspath(target),
        "exported": total,
        "sets": {
            set_name: {
                "exported": len(included[set_name]),
                "distribution": distributions[set_name],
                "skipped": skipped_counts[set_name],
            }
            for set_name in SET_NAMES
        },
        "skipped": skipped_counts,
    }


def source_path(sample: PlannedSample) -> str:
    """The on-disk source path stored for a planned sample.

    The path is used only to open the file locally; it is never copied
    into the package manifest.
    """
    return sample.source


def _verify_source(sample: PlannedSample, path_text: str) -> int:
    path = Path(path_text)
    try:
        if not path.exists() or path.is_symlink() and not path.is_file():
            raise ExportError(f"source file for {sample.digest} does not exist: {path_text}")
        if not path.is_file():
            raise ExportError(
                f"source for {sample.digest} is not a regular file: {path_text}"
            )
        size = path.stat().st_size
    except OSError as error:
        raise ExportError(f"cannot stat source for {sample.digest}: {error}") from error
    try:
        digest = hashlib.sha256()
        with path.open("rb") as stream:
            while True:
                chunk = stream.read(_CHUNK_SIZE)
                if not chunk:
                    break
                digest.update(chunk)
    except OSError as error:
        raise ExportError(f"cannot read source for {sample.digest}: {error}") from error
    if digest.hexdigest() != sample.digest:
        raise ExportError(
            f"source content for {sample.digest} does not match its saved digest "
            f"(actual: {digest.hexdigest()})"
        )
    return size


def _stream_member(
    archive: zipfile.ZipFile, info: zipfile.ZipInfo, sample: PlannedSample
) -> tuple[int, str]:
    """Write one source file into the archive without buffering it fully."""
    hasher = hashlib.sha256()
    size = 0
    with archive.open(info, "w", force_zip64=True) as member, Path(
        source_path(sample)
    ).open("rb") as stream:
        while True:
            chunk = stream.read(_CHUNK_SIZE)
            if not chunk:
                break
            hasher.update(chunk)
            size += len(chunk)
            member.write(chunk)
    return size, hasher.hexdigest()


def _build_manifest(
    plan: ExportPlan,
    included: dict[str, list[PlannedSample]],
    category_by_label: dict[str, str],
    skipped_counts: dict[str, int],
) -> dict[str, Any]:
    samples: list[dict[str, str]] = []
    distributions: dict[str, dict[str, int]] = {}
    for set_name in SET_NAMES:
        counts: dict[str, int] = {}
        for sample in included[set_name]:
            counts[sample.label] = counts.get(sample.label, 0) + 1
            extension = os.path.splitext(source_path(sample))[1]
            samples.append(
                {
                    "path": (
                        f"{set_name}/{category_by_label[sample.label]}/"
                        f"{sample.digest}{extension}"
                    ),
                    "set": set_name,
                    "sha256": sample.digest,
                }
            )
        distributions[set_name] = dict(sorted(counts.items()))
    samples.sort(key=lambda item: item["path"])

    total = len(samples)
    return {
        "schema_version": PACKAGE_SCHEMA_VERSION,
        "plan": plan.name,
        "seed": plan.seed,
        "ratios": {set_name: plan.ratios[set_name] for set_name in SET_NAMES},
        "sets": [
            {
                "name": set_name,
                "ratio": plan.ratios[set_name],
                "samples": len(included[set_name]),
                "skipped_unlabeled": skipped_counts[set_name],
                "distribution": distributions[set_name],
