def _write_target(target: Path, temporary: Path, write) -> None:
    """Create ``target`` exclusively via a temp file and atomic rename.

    An existing target (including a directory, a symlink or a broken link)
    is rejected untouched.  The temp file lives next to the target so the
    final replace is atomic on the same filesystem; failure or interruption
    leaves only the removable temp, never a partial target.
    """
    parent = target.parent if str(target.parent) else Path(".")
    parent.mkdir(parents=True, exist_ok=True)

    # Exclusive create: also the winner-takes-all gate for two concurrent
    # exports of the same target.  O_EXCL follows symlinks on Linux only to
    # fail, which is what we want.
    flags = os.O_WRONLY | os.O_CREAT | os.O_EXCL
    descriptor = os.open(temporary, flags, 0o644)
    try:
        with os.fdopen(descriptor, "wb") as stream:
            descriptor = -1
            write(stream)
            stream.flush()
            os.fsync(stream.fileno())
        # Refuse if the destination appeared after we created the temp.
        if target.exists() or target.is_symlink():
            raise ExportError(f"export target already exists: {target}")
        os.link(temporary, target)
        _fsync_directory(parent)
    except FileExistsError:
        if target.exists() or target.is_symlink():
            raise ExportError(f"export target already exists: {target}") from None
        raise
    except BaseException:
        raise
    finally:
        if descriptor >= 0:
            os.close(descriptor)
        temporary.unlink(missing_ok=True)


def _fsync_directory(directory: Path) -> None:
    try:
        descriptor = os.open(directory, os.O_RDONLY)
    except OSError:
        return
    try:
        os.fsync(descriptor)
    except OSError:
        pass
    finally:
        os.close(descriptor)

