    samples: list[dict[str, str]] = []
    distributions: dict[str, dict[str, int]] = {}
    for set_name in SET_NAMES:
        counts: dict[str, int] = {}
        for sample in included[set_name]:
            counts[sample.label] = counts.get(sample.label, 0) + 1
            extension = os.path.splitext(source_path(sample))[1]
            samples.append(
                {
                    "path": (
                        f"{set_name}/{category_by_label[sample.label]}/"
                        f"{sample.digest}{extension}"
                    ),
                    "set": set_name,
                    "sha256": sample.digest,
                }
            )
        distributions[set_name] = dict(sorted(counts.items()))
    samples.sort(key=lambda item: item["path"])

    total = len(samples)
    return {
        "schema_version": PACKAGE_SCHEMA_VERSION,
        "plan": plan.name,
        "seed": plan.seed,
        "ratios": {set_name: plan.ratios[set_name] for set_name in SET_NAMES},
        "sets": [
            {
                "name": set_name,
                "ratio": plan.ratios[set_name],
                "samples": len(included[set_name]),
                "skipped_unlabeled": skipped_counts[set_name],
                "distribution": distributions[set_name],
            }
            for set_name in SET_NAMES
        ],
        "categories": [
            {"label": label, "directory": category_by_label[label]}
            for label in sorted(category_by_label)
        ],
        "label_directories": {
            category_by_label[label]: label for label in sorted(category_by_label)
        },
        "skipped_unlabeled": {
            set_name: skipped_counts[set_name] for set_name in SET_NAMES
        },
        "samples_total": total,
        "samples": samples,
    }


